using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type"
        // Revert to old name for compatibility with existing documents
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key"
        // Revert to old format for compatibility with existing documents
        modelBuilder.Entity<Blog>().HasPartitionKey(e => e.Id);
        modelBuilder.Entity<Blog>().Property(e => e.Id)
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Breaking change 3: Indexes (HasIndex) are no longer supported on Cosmos
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking change 4: Raw SQL queries using old discriminator property
        // must be updated: WHERE c.Discriminator = 'Blog' -> WHERE c["$type"] = 'Blog'
        // (or keep old property name via HasDiscriminator above, then no SQL change needed)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }  }

// Value generator to preserve legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

